package com.pharmatrack.ai.client;

/**
 * Normalized result of an AI model completion invocation.
 *
 * @param outputText   the primary text generated by the model
 * @param model        the model identifier that generated the response
 * @param responseId   provider-assigned response identifier (e.g. resp_...) for tracing
 * @param inputTokens  number of prompt/instruction tokens consumed
 * @param outputTokens number of completion/reasoning tokens generated
 * @param totalTokens  total tokens accounted for by the provider
 */
public record LlmResponse(
        String outputText,
        String model,
        String responseId,
        int inputTokens,
        int outputTokens,
        int totalTokens
) {
}
